#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONNECTIONS 64
#define BUFFER_SIZE 1024

typedef struct connection {
    int id;
    int ref_count;
    char *recv_buffer;
    size_t recv_len;
    int state; // 0=idle, 1=active, 2=closing, 3=closed
    pthread_mutex_t lock;
    void (*on_close)(struct connection *);
    void (*on_data)(struct connection *, const char *, size_t);
} connection_t;

typedef struct {
    connection_t *slots[MAX_CONNECTIONS];
    pthread_mutex_t pool_lock;
    int active_count;
} connection_pool_t;

static connection_pool_t g_pool;

void pool_init(void) {
    memset(&g_pool, 0, sizeof(g_pool));
    pthread_mutex_init(&g_pool.pool_lock, NULL);
}

connection_t *connection_create(int id) {
    connection_t *conn = calloc(1, sizeof(connection_t));
    if (!conn) return NULL;
    conn->id = id;
    conn->ref_count = 1;
    conn->recv_buffer = malloc(BUFFER_SIZE);
    if (!conn->recv_buffer) { free(conn); return NULL; }
    conn->recv_len = 0;
    conn->state = 0;
    pthread_mutex_init(&conn->lock, NULL);
    return conn;
}

void connection_destroy(connection_t *conn) {
    if (!conn) return;
    pthread_mutex_destroy(&conn->lock);
    free(conn->recv_buffer);
    free(conn);
}

/* Decrement ref count; destroy if zero */
void connection_release(connection_t *conn) {
    if (!conn) return;
    pthread_mutex_lock(&conn->lock);
    conn->ref_count--;
    int should_free = (conn->ref_count <= 0);
    pthread_mutex_unlock(&conn->lock);
    if (should_free) {
        connection_destroy(conn);
    }
}

void connection_acquire(connection_t *conn) {
    if (!conn) return;
    pthread_mutex_lock(&conn->lock);
    conn->ref_count++;
    pthread_mutex_unlock(&conn->lock);
}

/* Remove connection from pool */
int pool_remove(int id) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (g_pool.slots[i] && g_pool.slots[i]->id == id) {
            g_pool.slots[i] = NULL;
            g_pool.active_count--;
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/* Add connection to pool */
int pool_add(connection_t *conn) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (!g_pool.slots[i]) {
            g_pool.slots[i] = conn;
            g_pool.active_count++;
            pthread_mutex_unlock(&g_pool.pool_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return 0;
}

/* Find connection by id */
connection_t *pool_find(int id) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (g_pool.slots[i] && g_pool.slots[i]->id == id) {
            connection_t *c = g_pool.slots[i];
            pthread_mutex_unlock(&g_pool.pool_lock);
            return c;
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return NULL;
}

/* Default close handler - triggers cleanup cascade */
void default_on_close(connection_t *conn) {
    if (!conn) return;
    conn->state = 3;
    pool_remove(conn->id);
    connection_release(conn); /* Release pool's reference */
}

/* Process received data - may trigger close */
void process_data(connection_t *conn, const char *data, size_t len) {
    if (!conn || !data || len == 0) return;

    pthread_mutex_lock(&conn->lock);
    if (conn->state >= 2) {
        pthread_mutex_unlock(&conn->lock);
        return;
    }
    conn->state = 1;
    pthread_mutex_unlock(&conn->lock);

    /* Check for disconnect command */
    if (len >= 4 && memcmp(data, "QUIT", 4) == 0) {
        pthread_mutex_lock(&conn->lock);
        conn->state = 2;
        pthread_mutex_unlock(&conn->lock);

        if (conn->on_close) {
            conn->on_close(conn); /* This calls connection_release */
        }
        return;
    }

    /* Buffer the data */
    pthread_mutex_lock(&conn->lock);
    size_t space = BUFFER_SIZE - conn->recv_len;
    size_t to_copy = len < space ? len : space;
    memcpy(conn->recv_buffer + conn->recv_len, data, to_copy);
    conn->recv_len += to_copy;
    pthread_mutex_unlock(&conn->lock);

    if (conn->on_data) {
        conn->on_data(conn, conn->recv_buffer, conn->recv_len);
    }
}

/* Handle a sequence of messages for a connection */
void handle_messages(int conn_id, const char **messages, size_t *lengths, int msg_count) {
    connection_t *conn = pool_find(conn_id);
    if (!conn) return;

    /* Acquire reference for this operation */
    connection_acquire(conn);

    for (int i = 0; i < msg_count; i++) {
        process_data(conn, messages[i], lengths[i]);

        /* After processing, check if connection is still valid.
         * We read state without lock for performance - 
         * the state transition to 3 (closed) is monotonic */
        if (conn->state == 3) {
            /* Connection was closed during processing.
             * Release our reference and stop. */
            connection_release(conn);
            return;
        }
    }

    connection_release(conn);
}

/* Batch processing: handle data from multiple connections */
void batch_process(int *conn_ids, const char **data, size_t *lengths, int count) {
    for (int i = 0; i < count; i++) {
        connection_t *conn = pool_find(conn_ids[i]);
        if (!conn) continue;

        process_data(conn, data[i], lengths[i]);
    }
}

/* Echo handler callback */
void echo_handler(connection_t *conn, const char *data, size_t len) {
    /* In real code this would send data back */
    (void)conn; (void)data; (void)len;
}

/* Setup a new connection with default handlers */
connection_t *setup_connection(int id) {
    connection_t *conn = connection_create(id);
    if (!conn) return NULL;

    conn->on_close = default_on_close;
    conn->on_data = echo_handler;

    /* Pool holds a reference */
    connection_acquire(conn);
    if (!pool_add(conn)) {
        connection_release(conn);
        connection_release(conn);
        return NULL;
    }

    return conn;
}
